func globalControlHome(global *GlobalControlConfig, nats natscell.Config) (string, error) {
	home := natscell.LinkHome
	if nats.Embedded == nil || nats.Embedded.Link == nil {
		var err error
		if home, err = interRegionLink(nats).GlobalControlHome(nats.Cell); err != nil {
			return "", err
		}
	}
	if global != nil && global.Home != "" && global.Home != home {
		return "", errors.New("global control home must agree with the interregion topology")
	}
	return home, nil
}

// interRegionLink returns the region's leaf topology material, or nil.
func interRegionLink(nats natscell.Config) *natscell.InterRegion {
	if nats.Embedded == nil {
		return nil
	}
	return nats.Embedded.InterRegion
}

// globalMirrorPeers are the regions whose durable mirror consumers the home
// region creates: every interregion peer, or none for a standalone home.
func globalMirrorPeers(nats natscell.Config) []string {
	if link := interRegionLink(nats); link != nil {
		return link.Peers
	}
	return nil
}

func (ir *InterRegion) GlobalControlHome(cell string) (string, error) {
	home := cell
	if ir != nil {
		home = ir.GlobalHome
		if ir.Topology != nil {
			if err := ir.matchTopology(cell, *ir.Topology); err != nil {
				return "", err
			}
			home = ir.Topology.Hub
		}
		if home != cell && !slices.Contains(ir.Peers, home) {
			return "", errors.New("interregion global home must be this region or a roster peer")
		}
	}
	if token, err := protocol.RegionToken(home); err != nil || token != home || token == protocol.GlobalScope {
		return "", errors.New("global control home must be a lowercase regional cell")
	}
	return home, nil
}

// rolloutKnownBad refuses placement admission until the mandatory rollout store opens.
type rolloutKnownBad struct {
	store atomic.Pointer[rollout.Store]
}

func newRolloutKnownBad() *rolloutKnownBad { return &rolloutKnownBad{} }

func (k *rolloutKnownBad) IsKnownBad(ctx context.Context, digest string) (bool, error) {
	store := k.store.Load()
	if store == nil {
		return false, errors.New("the rollout store is not open yet")
	}
	return store.IsKnownBad(ctx, digest)
}

func withKnownBad(config placement.Config, knownBad *rolloutKnownBad) placement.Config {
	if knownBad != nil {
		config.KnownBad = knownBad
	}
	return config
}

func logErrors(classes []logs.ReplyClass) []globalview.Error {
	var out []globalview.Error
	for _, class := range classes {
		out = append(out, globalview.Error{At: class.Last, Level: class.Level, Service: class.Service,
			Component: class.Component, Message: class.Message, Count: class.Count, Nodes: class.Nodes})
	}
	return out
}

func hostCredentialReloader(path string, running Config, identity ed25519.PrivateKey) func() (natscell.ClientMaterial, error) {
	return func() (natscell.ClientMaterial, error) {
		reloaded, err := LoadConfig(path)
		if err != nil {
			return natscell.ClientMaterial{}, err
		}
		if err := sameHostIdentityConfig(running, reloaded); err != nil {
			return natscell.ClientMaterial{}, err
		}
		key, err := readPrivateKey(reloaded.Host.IdentityKeyFile)
		if err != nil {
			return natscell.ClientMaterial{}, err
		}
		if !identity.Equal(key) {
			return natscell.ClientMaterial{}, errors.New("reloaded host identity key differs from the running agent")
		}
		return natscell.ClientMaterial{CredentialsFile: reloaded.NATS.CredentialsFile, TLS: reloaded.NATS.TLS}, nil
	}
}

// sameHostIdentityConfig accepts only credential path changes.
func sameHostIdentityConfig(running, reloaded Config) error {
	left, right := running.NATS, reloaded.NATS
	if left.Cell != right.Cell || left.Instance != right.Instance || left.Replicas != right.Replicas ||
		left.URL != right.URL || left.NKeySeedFile != right.NKeySeedFile ||
		left.Embedded != nil || right.Embedded != nil {
		return errors.New("reloaded host NATS configuration changes more than credentials")
	}
	hostLeft, hostRight := running.Host, reloaded.Host
	if !slices.Equal(hostLeft.Roles, hostRight.Roles) || hostLeft.Node != hostRight.Node ||
		hostLeft.Environment != hostRight.Environment || hostLeft.ControllerPublicKey != hostRight.ControllerPublicKey ||
		hostLeft.InstallRoot != hostRight.InstallRoot || hostLeft.StateRoot != hostRight.StateRoot ||
		hostLeft.ManagedRuntimeRoot != hostRight.ManagedRuntimeRoot || hostLeft.TerraBaseRoot != hostRight.TerraBaseRoot ||
		hostLeft.TSAuthRoot != hostRight.TSAuthRoot || hostLeft.WorkloadUID != hostRight.WorkloadUID ||
		hostLeft.WorkloadGID != hostRight.WorkloadGID || hostLeft.PollMillis != hostRight.PollMillis {
		return errors.New("reloaded host configuration changes more than credentials")
	}
	return nil
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

func readPrivateKey(path string) (ed25519.PrivateKey, error) {
	if path == "" {
		return nil, errors.New("private identity key file is required")
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, fmt.Errorf("open private key: %w", err)
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat private key: %w", err)
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("private key must be a regular file readable only by its owner")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("private key must be owned by this process user")
	}
	data, err := io.ReadAll(io.LimitReader(file, 128))
	if err != nil {
		return nil, fmt.Errorf("read private key: %w", err)
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
	if err != nil {
		return nil, fmt.Errorf("decode private key: %w", err)
	}
	if len(decoded) != ed25519.PrivateKeySize {
		return nil, errors.New("private key must contain 64 Ed25519 bytes")
	}
	return ed25519.PrivateKey(decoded), nil
}

type staticHostFleet struct {
	oci.Fleet
	instances map[string]oci.CloudInstance
	// observed, when set, runs before each static host observation.
	observed func()
}

func (fleet *staticHostFleet) ObserveStaticHost(_ context.Context, instanceID, node string) (oci.CloudInstance, error) {
	if fleet.observed != nil {
		fleet.observed()
	}
	instance, ok := fleet.instances[instanceID]
	if !ok || instance.FreeformTags["terrascale-host-node"] != node {
		return oci.CloudInstance{}, oci.ErrForeignResource
	}
	return instance, nil
}

// ObserveNamedHost returns the running instance named node, as the OCI
// observer does for a granted host.
func (fleet *staticHostFleet) ObserveNamedHost(_ context.Context, instanceID, node string) (oci.CloudInstance, error) {
	if fleet.observed != nil {
		fleet.observed()
	}
	instance, ok := fleet.instances[instanceID]
	if !ok || instance.DisplayName != node {
		return oci.CloudInstance{}, oci.ErrForeignResource
	}
	return instance, nil
}

