func (enrollment *managedHostEnrollment) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	if request.URL.Path == "/v1/runtime/worker-refresh" {
		enrollment.refreshRuntimeWorker(writer, request)
		return
	}
	if request.URL.Path == "/v1/runtime/worker-bind" {
		enrollment.bindRuntimeWorker(writer, request)
		return
	}
	if request.Method != http.MethodPost || request.URL.Path != "/v1/host-enrollment" || request.TLS == nil ||
		request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		http.Error(writer, "invalid host enrollment request", http.StatusBadRequest)
		return
	}
	snapshot := enrollment.fencer.Current()
	if !snapshot.CanMutate() {
		http.Error(writer, "regional authority is not writable", http.StatusServiceUnavailable)
		return
	}
	peerIP, _, err := net.SplitHostPort(request.RemoteAddr)
	if err != nil || net.ParseIP(peerIP) == nil {
		http.Error(writer, "direct private peer is required", http.StatusForbidden)
		return
	}
	wire, err := io.ReadAll(io.LimitReader(request.Body, hostenroll.MaxRequestBytes+1))
	if err != nil || len(wire) > hostenroll.MaxRequestBytes {
		http.Error(writer, "host enrollment request is too large", http.StatusRequestEntityTooLarge)
		return
	}
	enrollmentRequest, descriptor, err := hostenroll.ParseRequest(wire, time.Now().UTC())
	if err != nil {
		var historical hostenroll.Request
		if json.Unmarshal(wire, &historical, json.RejectUnknownMembers(true)) != nil ||
			historical.IssuedAt.IsZero() || !historical.IssuedAt.Before(time.Now().Add(-48*time.Hour)) {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		enrollmentRequest, descriptor, err = hostenroll.ParseRequest(wire, historical.IssuedAt.Add(time.Second))
		if err != nil {
			http.Error(writer, "host enrollment request is invalid", http.StatusBadRequest)
			return
		}
		grant, _, readErr := enrollment.grants.Read(request.Context(), enrollmentRequest.InstanceID)
		stored := grant.Request
		if enrollmentRequest.Operation == "renew" {
			stored = grant.RenewalRequest
		}
		if readErr != nil || grant.Disabled || !bytes.Equal(wire, stored) {
			http.Error(writer, "stale host request has no exact grant", http.StatusPreconditionFailed)
			return
		}
	}
	response, err := enrollment.enroll(request.Context(), snapshot.Epoch, peerIP, wire, enrollmentRequest, descriptor)
	if err != nil {
		if errors.Is(err, errStaleUnclaimedRenewal) {
			writer.Header().Set("X-TerraScale-Host-Enrollment-Error", staleUnclaimedRenewal)
			http.Error(writer, "stale unclaimed host renewal", http.StatusPreconditionFailed)
			return
		}
		http.Error(writer, "host enrollment held", http.StatusConflict)
		return
	}
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	_, _ = writer.Write(response)
}

func (enrollment *managedHostEnrollment) enroll(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if descriptor.IsStatic() {
		return enrollment.enrollStatic(ctx, epoch, peerIP, wire, request, descriptor)
	}
	ctx = authority.WithActiveWorkloadEffectContext(ctx)
	release, err := enrollment.beginActiveEffect(ctx, epoch, descriptor)
	if err != nil {
		return nil, err
	}
	defer release()
	return enrollment.enrollActive(ctx, epoch, peerIP, wire, request, descriptor)
}

func (enrollment *managedHostEnrollment) enrollStatic(ctx context.Context, epoch uint64, peerIP string, wire []byte,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) ([]byte, error) {
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if descriptor.Cell != enrollment.cell || descriptor.Region != string(enrollment.region) {
		return nil, errors.New("static host descriptor is outside this regional cell")
	}
	csr, err := hostenroll.ParseCSR(request.CSRPEM)
	if err != nil {
		return nil, err
	}
	instance, admission, err := enrollment.observeStatic(ctx, peerIP, request, descriptor)
	if err != nil {
		return nil, err
	}
	digest, err := descriptor.Digest()
	if err != nil {
		return nil, err
	}
	createKey := entityid.Derive("static-enrollment", enrollment.cell, descriptor.Node)
	var grant hostenroll.Grant
	var revision uint64
	if request.Operation == "renew" {
		prior, _, err := enrollment.grants.Read(ctx, request.InstanceID)
		if err != nil || prior.Disabled || prior.CreateKey != createKey || prior.DescriptorSHA256 != digest {
			return nil, errors.New("host renewal has no active exact enrollment grant")
		}
		var original hostenroll.Request
		if json.Unmarshal(prior.Request, &original, json.RejectUnknownMembers(true)) != nil ||
			original.IdentityPublicKey != request.IdentityPublicKey ||
			original.NATSUserPublicKey != request.NATSUserPublicKey || original.CSRPEM != request.CSRPEM {
			return nil, errors.New("host renewal changes an enrolled identity or CSR")
		}
		if time.Since(request.IssuedAt) > 5*time.Minute && !bytes.Equal(prior.RenewalRequest, wire) {
			return nil, errStaleUnclaimedRenewal
		}
		if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		grant, revision, err = enrollment.grants.ClaimRenew(ctx, request.InstanceID, wire, time.Now().UTC())
		if err != nil {
			return nil, err
		}
	} else {
		if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		grant, revision, err = enrollment.grants.Claim(ctx, hostenroll.Grant{SchemaVersion: 1,
			InstanceID: request.InstanceID, CreateKey: createKey, DescriptorSHA256: digest, Request: wire})
		if err != nil {
			return nil, err
		}
	}
	cached := grant.Response
	if request.Operation == "renew" {
		cached = grant.RenewalResponse
	}
	if len(cached) != 0 {
		if descriptor.IsController() {
			return enrollment.prepareRuntimeWorker(ctx, epoch, wire, cached)
		}
		return cached, enrollment.fencer.Guard(ctx, epoch)
	}
	jwt, chain, expires, err := enrollment.issuer.Issue(request, csr, descriptor.Node, time.Now().UTC())
	if err != nil {
		return nil, err
	}
	// The instance must still hold the peer address, under the admission it
	// registered with, when the credential is committed and released. A cell
	// spec adopted mid-request can change the admission: the registration
	// and response then settle on the one the last observation found.
	var responseWire []byte
	for attempt := 1; ; attempt++ {
		registration, err := enrollment.staticRegistration(ctx, request, descriptor, instance, admission)
		if err != nil {
			return nil, err
		}
		receipt, err := enrollment.controller.Register(ctx, registration)
		if err != nil {
			return nil, err
		}
		response := hostenroll.Response{SchemaVersion: 1, Operation: request.Operation,
			InstanceID: request.InstanceID, Node: descriptor.Node, DescriptorSHA256: digest,
			RequestSHA256: hostenroll.RequestSHA256(wire), Nonce: request.Nonce,
			RegistrationReceipt: receipt, Roles: admission.roles(),
			NATSUserJWT: jwt, TLSCertificatePEM: string(chain), ExpiresAt: expires}
		if enrollment.services != nil {
			response.NetBird = enrollment.services.netbird()
		}
		if err := response.Sign(enrollment.responseKey); err != nil {
			return nil, err
		}
		if responseWire, err = protocol.EncodeJSON(response); err != nil {
			return nil, err
		}
		if !descriptor.IsController() {
			responseWire, err = enrollment.prepareRuntimeWorker(ctx, epoch, wire, responseWire)
			if err != nil {
				return nil, err
			}
		}
		var again staticAdmission
		if instance, again, err = enrollment.observeStatic(ctx, peerIP, request, descriptor); err != nil {
			return nil, err
		}
		if reflect.DeepEqual(again, admission) {
			break
		}
		if attempt == 3 {
			return nil, errors.New("the cell spec keeps changing how this static host enrolls; retry")
		}
		admission = again
	}
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if descriptor.IsController() {
		current, currentRevision, err := hostenroll.ReadCurrentGrant(ctx, enrollment.js, request.InstanceID)
		if err != nil || currentRevision != revision || !reflect.DeepEqual(current, grant) ||
			!workerGrantAuthorizesPreparation(current, swarmruntime.WorkerRegistrationQuery{Request: wire, Response: responseWire}, time.Now().UTC()) {
			return nil, errors.New("controller enrollment no longer owns its exact live claim")
		}
		responseWire, err = enrollment.prepareRuntimeWorker(ctx, epoch, wire, responseWire)
		if err != nil {
			return nil, err
		}
	}
	if request.Operation == "renew" {
		err = enrollment.grants.FinishRenew(ctx, grant, revision, responseWire, time.Now().UTC())
	} else {
		_, err = enrollment.grants.Finish(ctx, grant, revision, responseWire)
	}
	if err != nil {
		return nil, err
	}
	// The commit is a KV CAS that fences no epoch: release the credential
	// only while this controller still holds authority. A held host retries
	// and the current leader replays the committed response.
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	return responseWire, nil
}

func (enrollment *managedHostEnrollment) observeStatic(ctx context.Context, peerIP string,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) (oci.CloudInstance, staticAdmission, error) {
	if err := refuseUnprovenPoolDescriptor(descriptor); err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	peer, capacity, listed := enrollment.staticMember(descriptor.Node)
	_, _, granted := enrollment.services.hostGrant(descriptor.Node)
	if !granted && !listed && enrollment.pool != nil {
		return enrollment.observePoolNode(ctx, peerIP, request, descriptor)
	}
	if granted || !listed {
		return enrollment.observeGranted(ctx, peerIP, request, descriptor)
	}
	if peer.Address.Addr().String() != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("static host is not a listed TerraBase member at its private address")
	}
	observer, ok := enrollment.fleet.(oci.StaticHostObserver)
	if !ok {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("regional fleet cannot observe static hosts")
	}
	instance, err := observer.ObserveStaticHost(ctx, request.InstanceID, descriptor.Node)
	if err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	if instance.PrivateIP != peerIP || instance.Metadata[hostboot.MetadataKey] != request.Descriptor {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("direct peer does not match the static OCI host")
	}
	return instance, staticAdmission{Capacity: capacity}, nil
}

// observeGranted authenticates a host the adopted cell spec grants: the
// direct peer holds the grant's address, and OCI shows the running instance
// of the descriptor's name holding it.
func (enrollment *managedHostEnrollment) observeGranted(ctx context.Context, peerIP string,
	request hostenroll.Request, descriptor hostboot.Descriptor,
) (oci.CloudInstance, staticAdmission, error) {
	grant, capacity, ok := enrollment.services.hostGrant(descriptor.Node)
	if !ok || grant.PrivateIP != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("static host is neither a listed TerraBase member nor granted its private address")
	}
	observer, ok := enrollment.fleet.(oci.NamedHostObserver)
	if !ok {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("regional fleet cannot observe granted hosts")
	}
	instance, err := observer.ObserveNamedHost(ctx, request.InstanceID, descriptor.Node)
	if err != nil {
		return oci.CloudInstance{}, staticAdmission{}, err
	}
	if instance.PrivateIP != peerIP {
		return oci.CloudInstance{}, staticAdmission{}, errors.New("direct peer does not match the granted instance")
	}
	return instance, staticAdmission{Grant: &grant, Capacity: capacity}, nil
}

func (enrollment *managedHostEnrollment) staticRegistration(ctx context.Context, request hostenroll.Request,
	descriptor hostboot.Descriptor, instance oci.CloudInstance, admission staticAdmission,
) (host.Registration, error) {
	registration := host.Registration{ID: entityid.Derive("host", enrollment.cell, descriptor.Node), Cell: enrollment.cell, Node: descriptor.Node,
		FailureDomain: strings.ToLower(instance.FaultDomain), Environment: enrollment.environment,
		PublicKey: request.IdentityPublicKey, NATSUserPublicKey: request.NATSUserPublicKey, Generation: 1}
	registration.Roles, registration.Capacity = []string{terrabase.Role}, admission.Capacity
	if grant := admission.Grant; grant != nil {
		registration.Roles, registration.Environment = grant.Roles, grant.Environment
	}
	if admission.Pool {
		registration.Roles = admission.Roles
	}
	statuses, err := enrollment.controller.ListHosts(ctx)
	if err != nil {
		return host.Registration{}, err
	}
	registration, err = nextStaticRegistration(registration, statuses)
	if err != nil {
		return host.Registration{}, err
	}
	// A scale-down retires its node's name for reuse. OCI has just shown a new
	// instance under that name, so it may take it again. The same host renewing
	// keeps its keys and stays retired: it may be draining.
	if admission.Pool && slices.ContainsFunc(statuses, func(status host.HostStatus) bool {
		return status.Registration.Node == descriptor.Node && status.Retired &&
			status.Registration.PublicKey != request.IdentityPublicKey
	}) {
		if err := enrollment.controller.Unretire(ctx, descriptor.Node); err != nil {
			return host.Registration{}, err
		}
	}
	return registration, nil
}

func runHostSetupWithMetadata(ctx context.Context, bundle hostenroll.PublicBundle,
	metadata hostenroll.InstanceMetadata, outputRoot string, output io.Writer, runtime hostSetupRuntime,
) error {
	if runtime.post == nil {
		return errors.New("host enrollment transport is unavailable")
	}
	if err := bundle.Validate(); err != nil {
		return err
	}
	currentDescriptor, err := hostboot.ParseHost(metadata.Wire)
	if err != nil || currentDescriptor != metadata.Descriptor || !validEnrollmentInstanceID(metadata.InstanceID) {
		return errors.New("current OCI host metadata is invalid")
	}
	if metadata.Descriptor.Cell != bundle.Cell || metadata.Descriptor.Region != bundle.Region {
		return errors.New("OCI host descriptor differs from image-pinned regional bundle")
	}
	if err := validateHostSetupRootOwner(outputRoot, runtime.ownerUID); err != nil {
		return err
	}
	secrets := outputRoot
	if runtime.secrets != "" {
		secrets = runtime.secrets
		if err := validateHostSetupRootOwner(secrets, runtime.ownerUID); err != nil {
			return err
		}
	}
	if runtime.identity != nil {
		if err := runtime.identity.restore(ctx, outputRoot, secrets); err != nil {
			return err
		}
	}
	renamed, err := resetRenamedHostEnrollment(outputRoot, secrets, metadata)
	if err != nil {
		return err
	}
	pending, err := readOrCreateHostEnrollment(ctx, secrets, metadata, runtime.identity)
	if err != nil {
		return err
	}
	var original hostenroll.Request
	if err := json.Unmarshal(pending.Request, &original, json.RejectUnknownMembers(true)); err != nil {
		return err
	}
	request, descriptor, err := hostenroll.ParseRequest(pending.Request, original.IssuedAt.Add(time.Second))
	if err != nil || request.InstanceID != metadata.InstanceID || request.Descriptor != string(metadata.Wire) ||
		descriptor != metadata.Descriptor || request.Operation != "enroll" {
		return errors.New("persisted host enrollment request differs from current OCI metadata")
	}
	// A renamed host's installed configuration names its old node.
	active := false
	if !renamed && runtime.identity != nil {
		if err := recoverHostCredentials(ctx, outputRoot, secrets, bundle, descriptor, pending, request, runtime); err != nil {
			return err
		}
	}
	if !renamed {
		if active, err = installedHostCredentialActive(outputRoot, secrets, bundle, descriptor.Node, pending, request); err != nil {
			return err
		}
	}
	if active && descriptor.IsController() {
		if _, err := os.Stat(filepath.Join(outputRoot, runtimeWorkerTransportFilename)); errors.Is(err, os.ErrNotExist) {
			active = false
		} else if err != nil {
			return err
		}
	}
	if active {
		_, _ = fmt.Fprintf(output, "host %s enrollment is current in cell %s\n", descriptor.Node, bundle.Cell)
		return cleanLegacyHostEnrollment(runtime, outputRoot, secrets)
	}
	requestWire := pending.Request
	if _, err := os.Stat(filepath.Join(outputRoot, "host.json")); err == nil && !renamed {
		requestWire, err = createRenewalRequest(outputRoot, pending, request)
		if err != nil {
			return err
		}
	}
	request, err = parsePersistedHostRequest(requestWire)
	if err != nil {
		return err
	}
	responseWire, err := runtime.post(ctx, bundle, requestWire)
	if status, ok := errors.AsType[*hostEnrollmentHTTPStatusError](err); ok &&
		status.Code == http.StatusPreconditionFailed && time.Since(request.IssuedAt) > 48*time.Hour {
		if request.Operation == "renew" {
			requestWire, err = createFreshRenewalRequest(outputRoot, pending, original)
		} else {
			requestWire, err = createFreshInitialRequest(ctx, secrets, pending, original, runtime.identity)
		}
		if err != nil {
			return err
		}
		request, err = parsePersistedHostRequest(requestWire)
		if err != nil {
			return err
		}
		responseWire, err = runtime.post(ctx, bundle, requestWire)
	}
	if status, ok := errors.AsType[*hostEnrollmentHTTPStatusError](err); ok &&
		status.Code == http.StatusPreconditionFailed && status.Kind == staleUnclaimedRenewal &&
		request.Operation == "renew" && time.Since(request.IssuedAt) > 5*time.Minute {
		requestWire, err = createFreshRenewalRequest(outputRoot, pending, original)
		if err != nil {
			return err
		}
		request, err = parsePersistedHostRequest(requestWire)
		if err != nil {
			return err
		}
		responseWire, err = runtime.post(ctx, bundle, requestWire)
	}
	if err != nil {
		return err
	}
	responseKey, err := bundle.ResponsePublicKey()
	if err != nil {
		return err
	}
	response, err := hostenroll.VerifyResponse(responseWire, responseKey, request, requestWire, descriptor)
	if err != nil && time.Since(request.IssuedAt) > 5*time.Minute {
		if request.Operation == "renew" {
			requestWire, err = createFreshRenewalRequest(outputRoot, pending, original)
		} else {
			requestWire, err = createRenewalRequest(outputRoot, pending, original)
		}
		if err != nil {
			return err
		}
		request, err = parsePersistedHostRequest(requestWire)
		if err != nil {
			return err
		}
		responseWire, err = runtime.post(ctx, bundle, requestWire)
		if err != nil {
			return err
		}
		response, err = hostenroll.VerifyResponse(responseWire, responseKey, request, requestWire, descriptor)
	}
	if err != nil {
		return err
	}
	if err := validateHostCredentials(bundle, descriptor.Node, pending, request, response); err != nil {
		return err
	}
	transport, err := protocol.EncodeJSON(hostenroll.WorkerTransport{Request: requestWire, Response: responseWire})
	if err != nil {
		return err
	}
	if err := writeAtomicHostFile(filepath.Join(outputRoot, runtimeWorkerTransportFilename), transport, 0o600); err != nil {
		return err
	}
	if err := installHostEnrollment(ctx, outputRoot, secrets, bundle, descriptor, pending, response, runtime.ownerUID, runtime.netbird); err != nil {
		return err
	}
	if request.Operation == "renew" {
		if err := os.Remove(filepath.Join(outputRoot, ".host-enrollment-renewal.json")); err != nil {
			return err
		}
	}
	_, _ = fmt.Fprintf(output, "host %s enrolled in cell %s\n", descriptor.Node, bundle.Cell)
	return cleanLegacyHostEnrollment(runtime, outputRoot, secrets)
}

func installHostEnrollment(ctx context.Context, root, secrets string, bundle hostenroll.PublicBundle, descriptor hostboot.Descriptor,
	pending pendingHostEnrollment, response hostenroll.Response, ownerUID uint32,
	bootstrapNetBird func(context.Context, string, client.Pin, netbird.Config) (bool, error),
) error {
	node := descriptor.Node
	responseWire, err := protocol.EncodeJSON(response)
	if err != nil {
		return err
	}
	sum := sha256.Sum256(responseWire)
	credentialRoot := filepath.Join(secrets, fmt.Sprintf("host-credentials-%x", sum[:12]))
	if err := os.Mkdir(credentialRoot, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
		return err
	}
	if err := validateHostSetupRootOwner(credentialRoot, ownerUID); err != nil {
		return err
	}
	seed, err := base64.StdEncoding.DecodeString(pending.NATSUserSeed)
	if err != nil {
		return err
	}
	defer clear(seed)
	creds, err := jwt.FormatUserConfig(response.NATSUserJWT, seed)
	if err != nil {
		return err
	}
	files := []struct {
		name string
		data []byte
		mode os.FileMode
	}{
		{"host-identity.key", []byte(pending.IdentityKey + "\n"), 0o600},
		{"host-nats.creds", creds, 0o600},
		{"host-tls-key.pem", []byte(pending.TLSPrivateKey), 0o600},
		{"host-tls-cert.pem", []byte(response.TLSCertificatePEM), 0o600},
		{"ca.pem", []byte(bundle.CAPEM), 0o644},
	}
	for _, file := range files {
		if err := writeAtomicHostFile(filepath.Join(credentialRoot, file.name), file.data, file.mode); err != nil {
			return err
		}
	}
	if response.NetBird != nil {
		_, err := os.Lstat(filepath.Join(root, "host.json"))
		if errors.Is(err, os.ErrNotExist) {
			if bootstrapNetBird == nil {
				return errors.New("host bootstrap NetBird configuration installer is unavailable")
			}
			if _, err := bootstrapNetBird(ctx, root, response.NetBird.Pin, response.NetBird.Enrollment); err != nil {
				return err
			}
		} else if err != nil {
			return err
		}
	}
	config := Config{Version: ConfigVersion, NATS: natscell.Config{Cell: bundle.Cell, Instance: node, Replicas: 3,
		URL: strings.Join(bundle.NATSURLs, ","), CredentialsFile: filepath.Join(credentialRoot, "host-nats.creds"),
		TLS: natscell.TLSFiles{CAFile: filepath.Join(credentialRoot, "ca.pem"),
			CertFile: filepath.Join(credentialRoot, "host-tls-cert.pem"), KeyFile: filepath.Join(credentialRoot, "host-tls-key.pem")}},
		Host: HostConfig{Node: node, Environment: bundle.Environment, Roles: []string{terrabase.Role},
			IdentityKeyFile:     filepath.Join(credentialRoot, "host-identity.key"),
			ControllerPublicKey: bundle.ControllerResponsePublicKey,
			InstallRoot:         bundle.InstallRoot, StateRoot: bundle.StateRoot,
			ManagedRuntimeRoot: bundle.ManagedRuntimeRoot,
			WorkloadUID:        bundle.WorkloadUID, WorkloadGID: bundle.WorkloadGID}}
	// A renewal regenerates the credentials, not the operator's host-local
	// options: carry them forward from the configuration being replaced.
	local, err := readHostLocalOptions(filepath.Join(root, "host.json"))
	if err != nil {
		return err
	}
	local.applyTo(&config.Host)
	// A granted host runs the roles its cell spec host grant names; any other
	// static host runs C# TerraBase members. Each role gets the image's root
	// unless the operator chose another one.
	if len(response.Roles) != 0 {
		config.Host.Roles = slices.Clone(response.Roles)
	}
	if slices.Contains(config.Host.Roles, tsauth.Role) && config.Host.TSAuthRoot == "" {
		config.Host.TSAuthRoot = filepath.Join(bundle.ManagedRuntimeRoot, "ts-auth")
	}
	if descriptor.IsStatic() && slices.Contains(config.Host.Roles, terrabase.Role) && config.Host.TerraBaseRoot == "" {
		config.Host.TerraBaseRoot = filepath.Join(bundle.ManagedRuntimeRoot, "terrabase")
	}
	// On a controller VM the controller holds the default observability port.
	if descriptor.IsController() {
		config.Observability.ListenAddress = controllerHostObservability
	}
	wire, err := protocol.EncodeJSON(config)
	if err != nil {
		return err
	}
	// The response is the credentials' public half; keep it for a reboot.
	if err := writeAtomicHostFile(filepath.Join(root, hostResponseFile), responseWire, 0o600); err != nil {
		return err
	}
	return writeAtomicHostFile(filepath.Join(root, "host.json"), wire, 0o600)
}

func writeAtomicHostFile(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	name := filepath.Base(path)
	nonce := make([]byte, 12)
	if _, err := rand.Read(nonce); err != nil {
		return err
	}
	temporary := filepath.Join(directory, "."+name+"."+base64.RawURLEncoding.EncodeToString(nonce))
	file, err := os.OpenFile(temporary, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return err
	}
	defer os.Remove(temporary)
	if _, err := file.Write(data); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(temporary, path); err != nil {
		return err
	}
	dir, err := os.Open(directory)
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}

func OpenGrantStore(ctx context.Context, js jetstream.JetStream, replicas int) (*GrantStore, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("host enrollment requires replicated JetStream")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: GrantBucket, History: 2, MaxValueSize: MaxGrantBytes,
		MaxBytes: 64 << 20, Storage: jetstream.FileStorage, Replicas: replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open host enrollment grants: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil || status.Config().Replicas != replicas {
		return nil, errors.New("host enrollment grant replication differs from regional quorum")
	}
	return &GrantStore{kv: kv, js: js}, nil
}

func grantKey(instanceID string) string {
	return entityid.Derive("host-enrollment", instanceID)
}

// Claim creates a grant once, or returns a completed exact replay. A changed
// key, nonce, CSR, or descriptor for the same OCI instance is held.
func (store *GrantStore) Claim(ctx context.Context, candidate Grant) (Grant, uint64, error) {
	if store == nil || store.kv == nil || candidate.SchemaVersion != 1 || candidate.InstanceID == "" ||
		!entityid.Valid(candidate.CreateKey) || len(candidate.DescriptorSHA256) != 64 ||
		len(candidate.Request) == 0 || len(candidate.Request) > 16<<10 || len(candidate.Response) != 0 || candidate.Disabled ||
		candidate.OwnerToken != "" || !candidate.LeaseUntil.IsZero() || candidate.IdentityResetOperationID != "" || candidate.SwarmMembership != nil {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant candidate is invalid"))
	}
	claimToken := make([]byte, 32)
	if _, err := rand.Read(claimToken); err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	candidate.OwnerToken = base64.RawURLEncoding.EncodeToString(claimToken)
	candidate.LeaseUntil = time.Now().UTC().Add(time.Minute)
	wire, err := json.Marshal(candidate)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	key := grantKey(candidate.InstanceID)
	if revision, err := store.kv.Create(ctx, key, wire); err == nil {
		return candidate, revision, nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return Grant{}, 0, fmt.Errorf("create host enrollment grant: %w", err)
	}
	entry, err := store.kv.Get(ctx, key)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(fmt.Errorf("read host enrollment grant: %w", err))
	}
	var current Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &current, json.RejectUnknownMembers(true)) != nil ||
		current.SchemaVersion != 1 || current.InstanceID != candidate.InstanceID || current.CreateKey != candidate.CreateKey ||
		current.DescriptorSHA256 != candidate.DescriptorSHA256 || !bytes.Equal(current.Request, candidate.Request) || current.Disabled {
		return Grant{}, 0, mutationNotApplied(errors.New("host enrollment grant differs from the immutable first request or is disabled"))
	}
	if len(current.Response) != 0 {
		return current, entry.Revision(), nil
	}
	if time.Now().Before(current.LeaseUntil) {
		return Grant{}, 0, mutationNotApplied(ErrGrantInProgress)
	}
	current.OwnerToken = candidate.OwnerToken
	current.LeaseUntil = candidate.LeaseUntil
	wire, err = json.Marshal(current)
	if err != nil {
		return Grant{}, 0, mutationNotApplied(err)
	}
	revision, err := store.kv.Update(ctx, key, wire, entry.Revision())
	if err != nil {
		wrapped := fmt.Errorf("recover host enrollment grant ownership: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, 0, mutationNotApplied(wrapped)
		}
		return Grant{}, 0, wrapped
	}
	return current, revision, nil
}

// Forget deletes instanceID's grant, so the instance enrolls afresh: ts-orch
// node rename re-enrolls a renamed static host under its new name (TS-609).
func (store *GrantStore) Forget(ctx context.Context, instanceID string) error {
	if store == nil || store.kv == nil || instanceID == "" {
		return mutationNotApplied(errors.New("host enrollment grant store is unavailable"))
	}
	if err := store.kv.Delete(ctx, grantKey(instanceID)); err != nil && !errors.Is(err, jetstream.ErrKeyNotFound) {
		return fmt.Errorf("forget host enrollment grant: %w", err)
	}
	return nil
}

// Finish persists exact signed bytes before any network response. A lost reply
// returns the identical response on the next exact request.
func (store *GrantStore) Finish(ctx context.Context, expected Grant, revision uint64, response []byte) (Grant, error) {
	if store == nil || store.kv == nil || revision == 0 || expected.Disabled || len(expected.Response) != 0 ||
		expected.OwnerToken == "" || !time.Now().Before(expected.LeaseUntil) ||
		len(response) == 0 || len(response) > 32<<10 {
		return Grant{}, mutationNotApplied(errors.New("host enrollment response cannot be committed"))
	}
	expected.Response = bytes.Clone(response)
	wire, err := json.Marshal(expected)
	if err != nil {
		return Grant{}, mutationNotApplied(err)
	}
	if _, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, revision); err != nil {
		wrapped := fmt.Errorf("commit host enrollment response: %w", err)
		if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return Grant{}, mutationNotApplied(wrapped)
		}
		return Grant{}, wrapped
	}
	return expected, nil
}

func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

func (store *GrantStore) Disable(ctx context.Context, instanceID string) (uint64, error) {
	for range 4 {
		grant, revision, err := store.Read(ctx, instanceID)
		if err != nil {
			return 0, err
		}
		if grant.Disabled {
			return revision, nil
		}
		grant.Disabled = true
		wire, err := json.Marshal(grant)
		if err != nil {
			return 0, err
		}
		next, err := store.kv.Update(ctx, grantKey(instanceID), wire, revision)
		if err == nil {
			return next, nil
		}
		if !errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return 0, err
		}
	}
	return 0, errors.New("host enrollment grant changed during disable")
}

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func (c *Controller) lockControlLog(ctx context.Context) error {
	c.controlLogInfoOnce.Do(func() { c.controlLogInfoGate = make(chan struct{}, 1) })
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case c.controlLogInfoGate <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func (enrollment *managedHostEnrollment) prepareRuntimeWorker(ctx context.Context, epoch uint64, request, response []byte) ([]byte, error) {
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	if enrollment.runtimeIdentity.Validate() != nil {
		return nil, errors.New("accepted root runtime identity is unavailable for worker enrollment")
	}
	_, descriptor, err := hostenroll.ParseRetainedWorkerRequest(request, time.Now().UTC())
	if err != nil {
		return nil, err
	}
	if descriptor.IsController() {
		return enrollment.prepareRuntimeControllerHost(ctx, epoch, request, response)
	}
	wire, err := swarmruntime.PrepareEnrolledWorker(ctx, enrollment.runtimeIdentity, swarmruntime.WorkerRegistrationQuery{Request: request, Response: response})
	if err != nil {
		return nil, err
	}
	if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
		return nil, err
	}
	return wire, nil
}

func (identity AcceptedIdentity) Validate() error {
	if identity.SchemaVersion != 1 || !entityid.Valid(identity.OperationID) || !entityid.Valid(identity.DeploymentID) ||
		identity.Origin != identityrekey.AcceptanceOriginInitial && identity.Origin != identityrekey.AcceptanceOriginRekey ||
		!entityid.Valid(identity.ClusterID) || !release.ValidEnvironment(identity.Environment) || !catalog.IsCell(identity.Cell) ||
		!slices.Equal(identity.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) ||
		!slices.Contains(identity.ControllerSlots, identity.Slot) || !slices.Contains(identity.ControllerSlots, identity.SeedSlot) ||
		len(identity.ControllerBindings) == 0 || len(identity.ControllerBindings) > 3 ||
		identity.AcceptedAt.IsZero() || identity.AcceptedAt.Location() != time.UTC ||
		identity.MaterialGenerationSHA256 != "" && !markerDigestRE.MatchString(identity.MaterialGenerationSHA256) ||
		identity.ManagedMaterial != nil && identity.ManagedMaterial.Validate() != nil {
		return ErrAcceptedIdentity
	}
	if err := validateAcceptedBroker(identity.Broker); err != nil {
		return err
	}
	localFound := false
	for i, binding := range identity.ControllerBindings {
		if !slices.Contains(identity.ControllerSlots, binding.Slot) || binding.validate(identity.Cell) != nil ||
			i > 0 && identity.ControllerBindings[i-1].Slot >= binding.Slot {
			return ErrAcceptedIdentity
		}
		if binding.Slot == identity.Slot {
			if binding != identity.localBinding() {
				return ErrAcceptedIdentity
			}
			localFound = true
		}
		for _, prior := range identity.ControllerBindings[:i] {
			if prior.InstanceOCID == binding.InstanceOCID || prior.PrimaryVNICOCID == binding.PrimaryVNICOCID ||
				prior.PrimaryPrivateIP == binding.PrimaryPrivateIP || prior.Store.ServerName == binding.Store.ServerName ||
				prior.Store.RaftNodeID == binding.Store.RaftNodeID {
				return ErrAcceptedIdentity
			}
		}
	}
	if !localFound || len(identity.ConfigSHA256) != 4 || !markerDigestRE.MatchString(identity.ConfigSHA256["controller.json"]) {
		return ErrAcceptedIdentity
	}
	for _, name := range bootstrap.ControllerConfigFileNames {
		if !markerDigestRE.MatchString(identity.ConfigSHA256[name]) {
			return ErrAcceptedIdentity
		}
	}
	if identityrekey.ValidateLaunchMaterialPins(identity.LaunchMaterialSHA256) != nil {
		return ErrAcceptedIdentity
	}
	return validateAcceptedReferences(identity)
}

