func nextStaticRegistration(registration host.Registration, statuses []host.HostStatus) (host.Registration, error) {
	for _, status := range statuses {
		current := status.Registration
		if current.Node != registration.Node {
			continue
		}
		registration.Generation = current.Generation
		if sameJSONValue(current, registration) {
			return registration, nil
		}
		if (current.PublicKey != registration.PublicKey || current.NATSUserPublicKey != registration.NATSUserPublicKey) &&
			!status.SessionExpiresAt.IsZero() {
			return host.Registration{}, fmt.Errorf("%s still has a current host session; its replacement enrolls once that session ends", registration.Node)
		}
		registration.Generation++
	}
	return registration, nil
}

func sameJSONValue(left, right host.Registration) bool {
	a, errA := protocol.EncodeJSON(left)
	b, errB := protocol.EncodeJSON(right)
	return errA == nil && errB == nil && bytes.Equal(a, b)
}

func (r *specRegistry) adopt(spec cellspec.Spec, revision uint64) {
	r.launches.Lock()
	defer r.launches.Unlock()
	r.mu.Lock()
	defer r.mu.Unlock()
	if revision <= r.revision {
		return
	}
	// A stored record only moves forward; an older signed spec written into
	// the record is a rollback, whatever its revision.
	if spec.Generation < r.current.Generation || spec.Generation == r.current.Generation && !sameSpec(spec, r.current) {
		slog.Error("stored cell spec would roll back the current spec; keeping it", observability.ComponentKey, "cellspec",
			"generation", spec.Generation, "current", r.current.Generation, "revision", revision)
		return
	}
	// The signers change first, and a spec whose signers are refused is not
	// adopted at all, so no consumer sees one generation's spec with
	// another's signers.
	if r.replaceSigners != nil {
		if err := r.replaceSigners(r.effectiveSigners(spec)); err != nil {
			slog.Error("stored cell spec signers refused; keeping the current spec", observability.ComponentKey, "cellspec",
				"generation", spec.Generation, "revision", revision, "error", err)
			return
		}
	}
	r.current, r.revision = spec, revision
	slog.Info("cell spec adopted", observability.ComponentKey, "cellspec", "generation", spec.Generation,
		"revision", revision, "roles", len(spec.Services))
	if r.changed != nil {
		profiles, specs := r.effectiveLocked()
		r.changed(profiles, specs)
	}
}

func (r *specRegistry) validateHostGrants(grants []cellspec.HostGrant, profiles map[string]WorkloadProfile) error {
	var members terrabase.Profile
	if effective, ok := profiles[terrabase.Role]; ok && len(effective.Env) != 0 {
		members, _ = terrabase.ParseProfile(effective.Env)
	}
	for _, grant := range grants {
		peer, member := members.Member(grant.Node, grant.PrivateIP)
		if member != slices.Contains(grant.Roles, terrabase.Role) || member && peer.Address.Addr().String() != grant.PrivateIP {
			return fmt.Errorf("host grant %q lists role %q exactly when %s lists the node at the grant's address",
				grant.Node, terrabase.Role, terrabase.EnvPeers)
		}
		for _, role := range grant.Roles {
			if _, ok := profiles[role]; !ok || slices.Contains(r.reserved, role) {
				return fmt.Errorf("host grant %q role %q has no service profile or belongs to placement", grant.Node, role)
			}
		}
	}
	return nil
}

// hostGrant returns the adopted spec's grant for node and the capacity of
// one replica of each of its roles.
func (r *specRegistry) hostGrant(node string) (cellspec.HostGrant, host.Capacity, bool) {
	if r == nil {
		return cellspec.HostGrant{}, host.Capacity{}, false
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	grant, ok := r.current.Grant(node)
	if !ok {
		return cellspec.HostGrant{}, host.Capacity{}, false
	}
	profiles, _ := r.effectiveLocked()
	var capacity host.Capacity
	for _, role := range grant.Roles {
		resources := profiles[role].Resources
		capacity.CPU += resources.CPU
		capacity.MemoryBytes += resources.MemoryBytes
		capacity.DiskBytes += resources.DiskBytes
	}
	return grant, capacity, true
}

func (r *specRegistry) profiles() map[string]WorkloadProfile {
	profiles, _ := r.effective()
	return profiles
}

func VerifyResponse(wire []byte, public ed25519.PublicKey, request Request, requestWire []byte, descriptor hostboot.Descriptor) (Response, error) {
	return verifyResponseAt(wire, public, request, requestWire, descriptor, time.Now())
}

func verifyResponseAt(wire []byte, public ed25519.PublicKey, request Request, requestWire []byte, descriptor hostboot.Descriptor, now time.Time) (Response, error) {
	if len(wire) == 0 || len(wire) > MaxResponseBytes || len(public) != ed25519.PublicKeySize {
		return Response{}, errors.New("host enrollment response is missing or too large")
	}
	var response Response
	if err := json.Unmarshal(wire, &response, json.RejectUnknownMembers(true)); err != nil {
		return Response{}, err
	}
	canonical, err := protocol.EncodeJSON(response)
	if err != nil || !bytes.Equal(canonical, wire) {
		return Response{}, errors.New("host enrollment response is not canonical")
	}
	digest, err := descriptor.Digest()
	if err != nil {
		return Response{}, err
	}
	if response.SchemaVersion != 1 || response.Operation != request.Operation || response.InstanceID != request.InstanceID ||
		response.Node != descriptor.Node || response.DescriptorSHA256 != digest ||
		response.RequestSHA256 != RequestSHA256(requestWire) || response.Nonce != request.Nonce ||
		response.RegistrationReceipt.Generation == 0 || response.RegistrationReceipt.Revision == 0 ||
		response.NATSUserJWT == "" || response.TLSCertificatePEM == "" || !now.Before(response.ExpiresAt) {
		return Response{}, errors.New("host enrollment response does not bind the request or has expired")
	}
	for i, role := range response.Roles {
		if !roleRE.MatchString(role) || i > 0 && response.Roles[i-1] >= role || i >= 32 {
			return Response{}, errors.New("host enrollment response roles are invalid")
		}
	}
	if response.NetBird != nil {
		if err := response.NetBird.Validate(descriptor.Cell); err != nil {
			return Response{}, fmt.Errorf("host enrollment NetBird pin: %w", err)
		}
	}
	signature, err := base64.StdEncoding.DecodeString(response.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize {
		return Response{}, errors.New("host enrollment response signature is invalid")
	}
	unsigned, err := response.unsignedWire()
	if err != nil || !ed25519.Verify(public, append(bytes.Clone(responseDomain), unsigned...), signature) {
		return Response{}, fmt.Errorf("host enrollment response signature verification failed: %w", errors.New("untrusted response"))
	}
	return response, nil
}

