func (enrollment *managedHostEnrollment) fenceTerminalGrants(ctx context.Context, epoch uint64,
	intent authority.TerminalIntent,
) error {
	if enrollment == nil || enrollment.grants == nil || enrollment.members == nil {
		return errors.New("managed terminal grant fencing is unavailable")
	}
	if err := enrollment.validateTerminalGrantIntent(intent); err != nil {
		return err
	}
	if epoch == 0 || enrollment.fencer.Current().Epoch != epoch {
		return authority.ErrFenced
	}
	reader, ok := enrollment.fencer.(authority.TerminalIntentReader)
	if !ok {
		return errors.New("terminal grant fencing requires authority marker access")
	}
	if _, err := reader.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
		return authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	for _, target := range intent.Targets {
		if target.InstanceID == "" {
			continue
		}
		fenced := false
		for range 4 {
			if err := enrollment.fencer.Guard(ctx, epoch); err != nil {
				return err
			}
			grant, revision, err := enrollment.grants.Read(ctx, target.InstanceID)
			if errors.Is(err, jetstream.ErrKeyNotFound) {
				expected := hostenroll.Grant{SchemaVersion: 1,
					InstanceID: target.InstanceID, CreateKey: target.HostCreateKey}
				_, _, err = enrollment.grants.TerminalFence(ctx, expected, 0, intent.OperationID)
				if errors.Is(err, hostenroll.ErrTerminalFenceConflict) {
					continue
				}
				if err != nil {
					return fmt.Errorf("create terminal grant tombstone for seat %s: %w", target.SeatID, err)
				}
			} else if err != nil {
				return fmt.Errorf("read terminal grant for seat %s: %w", target.SeatID, err)
			} else {
				if !isTerminalGrantTombstone(grant, target, intent.OperationID) {
					if err := enrollment.verifyTerminalGrantBinding(ctx, intent, target, grant, revision); err != nil {
						return fmt.Errorf("terminal grant for seat %s: %w", target.SeatID, err)
					}
				}
				if _, _, err := enrollment.grants.TerminalFence(ctx, grant, revision, intent.OperationID); err != nil {
					if errors.Is(err, hostenroll.ErrTerminalFenceConflict) {
						continue
					}
					return fmt.Errorf("fence terminal grant for seat %s: %w", target.SeatID, err)
				}
			}
			if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
				return fmt.Errorf("terminal grant fence readback for seat %s: %w", target.SeatID, err)
			}
			fenced = true
			break
		}
		if !fenced {
			return fmt.Errorf("terminal grant for seat %s changed repeatedly during fencing", target.SeatID)
		}
	}
	return enrollment.settleFencedEnrollmentEffects(ctx, epoch, intent)
}

func (enrollment *managedHostEnrollment) settleFencedEnrollmentEffects(ctx context.Context, epoch uint64,
	intent authority.TerminalIntent,
) error {
	ledger, ok := enrollment.fencer.(terminalEnrollmentEffectLedger)
	if !ok {
		return errors.New("terminal grant fencing requires durable enrollment-effect settlement")
	}
	scope := authority.WorkloadScope{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID}
	pending, err := ledger.ListPendingEnrollmentEffects(ctx, scope)
	if err != nil {
		return err
	}
	targets := make(map[string]authority.TerminalTarget, len(intent.Targets))
	for _, target := range intent.Targets {
		if target.InstanceID != "" {
			targets[target.InstanceID] = target
		}
	}
	for _, effect := range pending {
		target, exists := targets[effect.InstanceID]
		if !exists || effect.Epoch > epoch {
			return fmt.Errorf("unmatched enrollment effect %s blocks terminal admission", effect.EffectID)
		}
		if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
			return fmt.Errorf("pending enrollment effect %s lacks its exact disabled grant fence: %w", effect.EffectID, err)
		}
		if effect.Epoch == epoch {
			_, err = ledger.SettleEnrollmentEffect(ctx, epoch, scope,
				effect.EffectID, effect.InstanceID, effect.Sequence)
		} else {
			verifyFence := func(verifyCtx context.Context) error {
				return enrollment.verifyTerminalGrantTarget(verifyCtx, intent, target)
			}
			_, err = ledger.SettleFencedEnrollmentEffect(ctx, epoch, scope,
				effect.EffectID, effect.InstanceID, effect.Sequence, verifyFence)
		}
		if err != nil {
			return fmt.Errorf("settle terminally fenced enrollment effect %s: %w", effect.EffectID, err)
		}
	}
	pending, err = ledger.ListPendingEnrollmentEffects(ctx, scope)
	if err != nil {
		return err
	}
	if len(pending) != 0 {
		return errors.New("unsettled enrollment effects remain after exact grant fencing")
	}
	return nil
}

func (enrollment *managedHostEnrollment) validateTerminalGrantIntent(intent authority.TerminalIntent) error {
	if err := intent.Validate(); err != nil || intent.Cell != enrollment.cell ||
		intent.Region != string(enrollment.region) || intent.Owner != enrollment.owner ||
		intent.FleetGeneration != enrollment.generation {
		return errors.New("terminal grant intent differs from the current regional fleet")
	}
	return nil
}

func isTerminalGrantTombstone(grant hostenroll.Grant, target authority.TerminalTarget,
	operationID string,
) bool {
	return grant.SchemaVersion == 1 && grant.InstanceID == target.InstanceID &&
		grant.CreateKey == target.HostCreateKey && grant.Disabled &&
		grant.TerminalOperationID == operationID && grant.DescriptorSHA256 == "" &&
		len(grant.Request) == 0 && len(grant.Response) == 0 && grant.OwnerToken == "" &&
		grant.LeaseUntil.IsZero() && len(grant.RenewalRequest) == 0 &&
		len(grant.RenewalResponse) == 0 && grant.RenewalToken == "" &&
		grant.RenewalLeaseUntil.IsZero()
}

func (enrollment *managedHostEnrollment) verifyTerminalGrantTarget(ctx context.Context,
	intent authority.TerminalIntent, target authority.TerminalTarget,
) error {
	if target.InstanceID == "" {
		return nil
	}
	grant, revision, err := enrollment.grants.Read(ctx, target.InstanceID)
	if err != nil {
		return err
	}
	if revision == 0 || !grant.Disabled || grant.TerminalOperationID != intent.OperationID ||
		grant.InstanceID != target.InstanceID || grant.CreateKey != target.HostCreateKey {
		return errors.New("grant is not the exact disabled terminal fence")
	}
	if isTerminalGrantTombstone(grant, target, intent.OperationID) {
		return nil
	}
	if err := enrollment.verifyTerminalGrantBinding(ctx, intent, target, grant, revision); err != nil {
		return err
	}
	return nil
}

// verifyTerminalGrantFence is a read-only proof used before marker commit.
// Every inventory target with an instance ID must have an exact disabled
// grant or create-if-absent tombstone tied to this terminal operation.
func (enrollment *managedHostEnrollment) verifyTerminalGrantFence(ctx context.Context,
	intent authority.TerminalIntent,
) error {
	if enrollment == nil || enrollment.grants == nil || enrollment.members == nil {
		return errors.New("managed terminal grant readback is unavailable")
	}
	if err := enrollment.validateTerminalGrantIntent(intent); err != nil {
		return err
	}
	for _, target := range intent.Targets {
		if err := enrollment.verifyTerminalGrantTarget(ctx, intent, target); err != nil {
			return fmt.Errorf("terminal grant for seat %s: %w", target.SeatID, err)
		}
	}
	return nil
}

func (store *GrantStore) TerminalFence(ctx context.Context, expected Grant, expectedRevision uint64,
	operationID string,
) (Grant, uint64, error) {
	if store == nil || store.kv == nil || expected.SchemaVersion != 1 || expected.InstanceID == "" ||
		expected.CreateKey == "" || !validTerminalOperationID(operationID) {
		return Grant{}, 0, errors.New("terminal enrollment grant fence identity is invalid")
	}
	if expectedRevision == 0 {
		if expected.DescriptorSHA256 != "" || len(expected.Request) != 0 || len(expected.Response) != 0 ||
			expected.Disabled || expected.OwnerToken != "" || !expected.LeaseUntil.IsZero() ||
			len(expected.RenewalRequest) != 0 || len(expected.RenewalResponse) != 0 ||
			expected.RenewalToken != "" || !expected.RenewalLeaseUntil.IsZero() || expected.TerminalOperationID != "" || expected.IdentityResetOperationID != "" || expected.SwarmMembership != nil {
			return Grant{}, 0, errors.New("absent terminal grant fence contains enrollment state")
		}
		tombstone := Grant{SchemaVersion: 1, InstanceID: expected.InstanceID,
			CreateKey: expected.CreateKey, Disabled: true, TerminalOperationID: operationID}
		wire, err := json.Marshal(tombstone)
		if err != nil {
			return Grant{}, 0, err
		}
		revision, err := store.kv.Create(ctx, grantKey(expected.InstanceID), wire)
		if err == nil {
			return tombstone, revision, nil
		}
		if !errors.Is(err, jetstream.ErrKeyExists) {
			return Grant{}, 0, fmt.Errorf("create terminal enrollment grant tombstone: %w", err)
		}
		current, revision, readErr := store.Read(ctx, expected.InstanceID)
		if readErr != nil {
			return Grant{}, 0, readErr
		}
		if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	if isTerminalTombstone(expected, expected.InstanceID, expected.CreateKey, operationID) {
		current, revision, err := store.Read(ctx, expected.InstanceID)
		if err != nil {
			return Grant{}, 0, err
		}
		if revision == expectedRevision && isTerminalTombstone(current, expected.InstanceID,
			expected.CreateKey, operationID) && sameGrant(current, expected) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}

	if len(expected.Request) == 0 || len(expected.DescriptorSHA256) != 64 ||
		expected.TerminalOperationID != "" && expected.TerminalOperationID != operationID {
		return Grant{}, 0, errors.New("existing terminal grant fence lacks exact grant pins")
	}
	current, revision, err := store.Read(ctx, expected.InstanceID)
	if err != nil {
		return Grant{}, 0, err
	}
	if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) {
		if current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
			return current, revision, nil
		}
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	if current.Disabled && current.TerminalOperationID == operationID &&
		current.InstanceID == expected.InstanceID && current.CreateKey == expected.CreateKey &&
		current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
		return current, revision, nil
	}
	if revision != expectedRevision || !sameGrant(current, expected) {
		return Grant{}, 0, ErrTerminalFenceConflict
	}
	current.Disabled = true
	current.TerminalOperationID = operationID
	wire, err := json.Marshal(current)
	if err != nil {
		return Grant{}, 0, err
	}
	nextRevision, err := store.kv.Update(ctx, grantKey(expected.InstanceID), wire, expectedRevision)
	if err == nil {
		return current, nextRevision, nil
	}
	if !errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return Grant{}, 0, fmt.Errorf("disable terminal enrollment grant: %w", err)
	}
	current, revision, readErr := store.Read(ctx, expected.InstanceID)
	if readErr != nil {
		return Grant{}, 0, readErr
	}
	if isTerminalTombstone(current, expected.InstanceID, expected.CreateKey, operationID) &&
		current.DescriptorSHA256 == expected.DescriptorSHA256 && bytes.Equal(current.Request, expected.Request) {
		return current, revision, nil
	}
	return Grant{}, 0, ErrTerminalFenceConflict
}

func (store *GrantStore) Read(ctx context.Context, instanceID string) (Grant, uint64, error) {
	if store == nil || store.kv == nil || instanceID == "" {
		return Grant{}, 0, errors.New("host enrollment grant store is unavailable")
	}
	entry, err := store.kv.Get(ctx, grantKey(instanceID))
	if err != nil {
		return Grant{}, 0, err
	}
	var grant Grant
	if len(entry.Value()) > MaxGrantBytes || json.Unmarshal(entry.Value(), &grant, json.RejectUnknownMembers(true)) != nil || grant.InstanceID != instanceID {
		return Grant{}, 0, errors.New("host enrollment grant is corrupt")
	}
	return grant, entry.Revision(), nil
}

// fakeIdentityRecord is a Vault record: its CURRENT value and versions.
type fakeIdentityRecord struct {
	value     []byte
	version   int64
	published int
}

func (fake *fakeIdentityRecord) record() *hostIdentityRecord {
	return &hostIdentityRecord{
		read: func(context.Context) (string, int64, []byte, error) {
			return "ocid1.vaultsecret.oc1.sa-saopaulo-1.record", fake.version, bytes.Clone(fake.value), nil
		},
		publish: func(_ context.Context, _ string, expected int64, value []byte) (int64, error) {
			if expected != fake.version {
				return 0, os.ErrExist
			}
			fake.value, fake.version = bytes.Clone(value), fake.version+1
			fake.published++
			return fake.version, nil
		}}
}

func (record *hostIdentityRecord) restore(ctx context.Context, legacy, secrets string) error {
	path := filepath.Join(secrets, pendingHostEnrollmentFile)
	if _, err := os.Lstat(path); !errors.Is(err, os.ErrNotExist) {
		return err
	}
	value, err := record.current(ctx)
	if err != nil {
		return err
	}
	defer clear(value)
	old, err := os.ReadFile(filepath.Join(legacy, pendingHostEnrollmentFile))
	if errors.Is(err, os.ErrNotExist) {
		return writeAtomicHostFile(path, value, 0o600)
	}
	if err != nil {
		return err
	}
	defer clear(old)
	if !bytes.Equal(old, value) && liveLegacyIdentity(legacy, old) {
		if err := record.save(ctx, old); err != nil {
			return err
		}
		value = old
	}
	if err := writeAtomicHostFile(path, value, 0o600); err != nil {
		return err
	}
	if err := os.Remove(filepath.Join(legacy, pendingHostEnrollmentFile)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

// liveLegacyIdentity reports whether host.json names on-disk credentials
// issued for the identity in wire: an identity key file below legacy that
// holds its key.
func liveLegacyIdentity(legacy string, wire []byte) bool {
	var pending pendingHostEnrollment
	if json.Unmarshal(wire, &pending) != nil || pending.IdentityKey == "" {
		return false
	}
	config, err := LoadConfig(filepath.Join(legacy, "host.json"))
	if err != nil || filepath.Dir(filepath.Dir(config.Host.IdentityKeyFile)) != legacy {
		return false
	}
	key, err := os.ReadFile(config.Host.IdentityKeyFile)
	defer clear(key)
	return err == nil && string(key) == pending.IdentityKey+"\n"
}

// current reads the record's CURRENT version and remembers which one it is.
func (record *hostIdentityRecord) current(ctx context.Context) ([]byte, error) {
	id, version, value, err := record.read(ctx)
	if err != nil {
		return nil, fmt.Errorf("read the host enrollment identity from Vault: %w", err)
	}
	record.id, record.version = id, version
	return value, nil
}

// save publishes a changed identity before host-setup writes or uses it.
func (record *hostIdentityRecord) save(ctx context.Context, wire []byte) error {
	if record == nil {
		return nil
	}
	if record.id == "" {
		value, err := record.current(ctx)
		clear(value)
		if err != nil {
			return err
		}
	}
	version, err := record.publish(ctx, record.id, record.version, wire)
	if err != nil {
		return fmt.Errorf("publish the host enrollment identity to Vault: %w", err)
	}
	record.version = version
	return nil
}

// removeLegacyHostEnrollment deletes the enrollment files a host kept below
// root before its identity and credentials moved to memory, once host.json
// names credentials in secrets: the identity is in Vault, and the
// credentials are renewed from it.
func removeLegacyHostEnrollment(root, secrets string) error {
	config, err := LoadConfig(filepath.Join(root, "host.json"))
	if err != nil {
		return err
	}
	if filepath.Dir(filepath.Dir(config.NATS.CredentialsFile)) != secrets {
		return nil
	}
	entries, err := os.ReadDir(root)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		name := entry.Name()
		if name == pendingHostEnrollmentFile ||
			entry.IsDir() && strings.HasPrefix(name, "host-credentials-") {
			if err := os.RemoveAll(filepath.Join(root, name)); err != nil {
				return err
			}
		}
	}
	dir, err := os.Open(root)
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}

// recoverHostCredentials reinstalls, in secrets, the credentials host.json
// names when they are missing there: after a reboot from the saved response,
// and once from the on-disk credentials an earlier release installed. Only a
// response that still validates against the enrolled identity is reused;
// otherwise host-setup renews or enrolls as before.
func recoverHostCredentials(ctx context.Context, root, secrets string, bundle hostenroll.PublicBundle,
	descriptor hostboot.Descriptor, pending pendingHostEnrollment, request hostenroll.Request, runtime hostSetupRuntime,
) error {
	config, err := LoadConfig(filepath.Join(root, "host.json"))
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	var response hostenroll.Response
	switch filepath.Dir(filepath.Dir(config.NATS.CredentialsFile)) {
	case secrets:
		complete := true
		for _, path := range []string{config.Host.IdentityKeyFile, config.NATS.CredentialsFile,
			config.NATS.TLS.KeyFile, config.NATS.TLS.CertFile, config.NATS.TLS.CAFile} {
			if _, err := os.Stat(path); err != nil {
				complete = false
			}
		}
		if complete {
			return nil
		}
		wire, err := os.ReadFile(filepath.Join(root, hostResponseFile))
		if err != nil || json.Unmarshal(wire, &response, json.RejectUnknownMembers(true)) != nil {
			return nil
		}
	case root:
		chain, chainErr := os.ReadFile(config.NATS.TLS.CertFile)
		creds, credsErr := os.ReadFile(config.NATS.CredentialsFile)
		defer clear(creds)
		if chainErr != nil || credsErr != nil {
			return nil
		}
		raw, err := nkeys.ParseDecoratedJWT(creds)
		block, _ := pem.Decode(chain)
		if err != nil || block == nil {
			return nil
		}
		leaf, err := x509.ParseCertificate(block.Bytes)
		if err != nil {
			return nil
		}
		response = hostenroll.Response{NATSUserJWT: raw, TLSCertificatePEM: string(chain), ExpiresAt: leaf.NotAfter,
			Roles: config.Host.Roles}
	default:
		return nil
	}
	if !time.Now().Before(response.ExpiresAt) || validateHostCredentials(bundle, descriptor.Node, pending, request, response) != nil {
		return nil
	}
	return installHostEnrollment(ctx, root, secrets, bundle, descriptor, pending, response, runtime.ownerUID, runtime.netbird)
}

func hostMemoryRuntime(cfg Config) (bool, selfupdate.Layout, string) {
	layout := selfupdate.NewLayout(selfUpdateRoot(cfg.Host.SelfUpdateRoot))
	if cfg.Host.ManagedRuntimeRoot == "" {
		return false, layout, ""
	}
	dirs := []string{filepath.Join(cfg.Host.ManagedRuntimeRoot, "roles")}
	if cfg.Host.TerraBaseRoot != "" {
		dirs = append(dirs, filepath.Join(cfg.Host.TerraBaseRoot, "tls"))
	}
	onDisk := false
	for _, dir := range dirs {
		if vaultsecret.RequireMemoryFilesystem(dir) != nil {
			onDisk = true
		}
	}
	if _, err := os.Lstat(memoryPrepareMarker); !errors.Is(err, os.ErrNotExist) {
		return true, layout, ""
	}
	current, currentErr := layout.Current()
	knownGood, knownGoodErr := layout.KnownGood()
	if !onDisk || currentErr != nil || knownGoodErr != nil || current == "" || knownGood == "" || knownGood == current {
		return true, layout, ""
	}
	slog.Warn("the prepare before this start predates in-memory runtime secrets; the on-disk layout serves until this release is known-good",
		"release", current, "known_good", knownGood)
	return false, layout, current
}

// memoryPrepareMarker is selfupdate.MemoryPrepareMarker; tests replace it.
var memoryPrepareMarker = selfupdate.MemoryPrepareMarker

func RequireMemoryFilesystem(directory string) error {
	file, err := os.Open(directory)
	if err != nil {
		return err
	}
	defer file.Close()
	var fs unix.Statfs_t
	if err := unix.Fstatfs(int(file.Fd()), &fs); err != nil || fs.Type != unix.TMPFS_MAGIC || !SwapOff() {
		return errors.New("Vault runtime files require tmpfs with swap disabled")
	}
	return nil
}

// SwapOff reports whether no swap is active. sysinfo(2) needs no /proc, so
// it also answers inside units with ProcSubset=pid, such as the controller.
func SwapOff() bool {
	var info unix.Sysinfo_t
	return unix.Sysinfo(&info) == nil && info.Totalswap == 0
}

func (layout Layout) Current() (string, error) { return layout.readLink(currentLink) }

// KnownGood returns the digest the known-good link points at, or "" when
// the link is absent: the last release a unit confirmed with a version
// proof. Nothing else moves it, so a restore, an unreadable record or the
// seed never make a release that has not proved itself the delegate.
func (layout Layout) KnownGood() (string, error) { return layout.readLink(knownGoodLink) }

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

func LoadConfig(path string) (Config, error) {
	if path == "" {
		return Config{}, errors.New("--config is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return Config{}, fmt.Errorf("stat config: %w", err)
	}
	if info.Size() > maxConfigBytes {
		return Config{}, errors.New("config is too large")
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}, fmt.Errorf("read config: %w", err)
	}
	cfg, err := decodeConfig(data)
	if err != nil {
		return Config{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Observability.Validate(); err != nil {
		return Config{}, fmt.Errorf("observability config: %w", err)
	}
	if api := cfg.Controller.MachinesAPI; api != nil {
		if err := api.Validate(); err != nil {
			return Config{}, err
		}
	}
	return cfg, nil
}

// decodeConfig strictly decodes config bytes and keeps them as the config's wire.
func decodeConfig(data []byte) (Config, error) {
	var cfg Config
	if err := protocol.DecodeStrict(data, &cfg, maxConfigBytes); err != nil {
		return Config{}, err
	}
	if cfg.Version != ConfigVersion {
		return Config{}, fmt.Errorf("config version must be %d, got %d", ConfigVersion, cfg.Version)
	}
	cfg.wire = data
	return cfg, nil
}

func readHostLocalOptions(path string) (hostLocalOptions, error) {
	file, err := os.Open(path)
	if errors.Is(err, os.ErrNotExist) {
		return hostLocalOptions{}, nil
	}
	if err != nil {
		return hostLocalOptions{}, fmt.Errorf("read existing host config: %w", err)
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, 1<<20+1))
	if err != nil {
		return hostLocalOptions{}, fmt.Errorf("read existing host config: %w", err)
	}
	if len(data) > 1<<20 {
		return hostLocalOptions{}, errors.New("existing host config is too large")
	}
	if _, err := decodeConfig(data); err != nil {
		return hostLocalOptions{}, fmt.Errorf("decode existing host config %s (repair it before renewing): %w", path, err)
	}
	var existing struct {
		Host hostLocalOptions `json:"host"`
	}
	if err := json.Unmarshal(data, &existing); err != nil {
		return hostLocalOptions{}, fmt.Errorf("decode existing host config %s (repair it before renewing): %w", path, err)
	}
	return existing.Host, nil
}
